-- /modules/objects/db/upgrade_2026-10-09_objects_without_client.sql
-- Import via phpMyAdmin on an EXISTING database (select the app database first).
-- New objects are created without client and without activity (activities come later from the inquiry).

SET FOREIGN_KEY_CHECKS = 0;

ALTER TABLE `objects_project_schedules` DROP FOREIGN KEY IF EXISTS `fk_ops_client`;

ALTER TABLE `objects_project_schedules`
  MODIFY `client_id` INT DEFAULT NULL COMMENT 'Опционално - клиентът вече не се избира при създаване на обект',
  MODIFY `activity_type_id` INT DEFAULT NULL COMMENT 'Връзка с objects_activity_types',
  MODIFY `total_quantity` DECIMAL(10,2) NOT NULL DEFAULT 0 COMMENT 'Общо количество (напр. 120)',
  MODIFY `daily_productivity_plan` DECIMAL(10,2) NOT NULL DEFAULT 0 COMMENT 'План за дневна производителност (напр. 20)',
  MODIFY `planned_days` DECIMAL(10,2) NOT NULL DEFAULT 0 COMMENT 'Планувани дни по договор';

-- Clean up any placeholder 0 values so the foreign key can be re-created
UPDATE `objects_project_schedules` SET `client_id` = NULL
  WHERE `client_id` IS NOT NULL AND `client_id` NOT IN (SELECT `client_id` FROM `clients_main`);

ALTER TABLE `objects_project_schedules`
  ADD CONSTRAINT `fk_ops_client` FOREIGN KEY (`client_id`) REFERENCES `clients_main` (`client_id`) ON DELETE SET NULL;

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================
-- DATA (from work_files/module_objects). Safe to re-run: existing ids are updated.
-- ============================================================

SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;

-- Activity types referenced by objects_machine_activities (9 = Торкрет; unit of measure is a guess - adjust if needed)

-- New main activity "Сондиране" (unit of measure is a guess - adjust if needed)
SELECT 'Сондиране', 'м' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `objects_activity_types` WHERE `activity_name` = 'Сондиране');

-- clients_main.sql
ON DUPLICATE KEY UPDATE
  `client_name`=VALUES(`client_name`),
  `client_address`=VALUES(`client_address`),
  `primary_contact_name`=VALUES(`primary_contact_name`),
  `primary_contact_phone`=VALUES(`primary_contact_phone`),
  `primary_contact_email`=VALUES(`primary_contact_email`),
  `primary_contact_notes`=VALUES(`primary_contact_notes`),
  `additional_contacts`=VALUES(`additional_contacts`),
  `general_notes`=VALUES(`general_notes`),
  `internal_notes`=VALUES(`internal_notes`),
  `created_at`=VALUES(`created_at`),
  `updated_at`=VALUES(`updated_at`);

-- heavy_machines.sql
ON DUPLICATE KEY UPDATE
  `machine_name`=VALUES(`machine_name`),
  `date_created`=VALUES(`date_created`),
  `date_modified`=VALUES(`date_modified`);

-- objects_machine_activities.sql
ON DUPLICATE KEY UPDATE
  `machine_id`=VALUES(`machine_id`),
  `activity_type_id`=VALUES(`activity_type_id`),
  `capability_name`=VALUES(`capability_name`);

SET FOREIGN_KEY_CHECKS = 1;
